import {helpText,parseMessage} from './wa-commands.js';
export const sampleCatalog=[{id:'example_light',name:'Luz da sala',aliases:['luz principal'],actions:{on:true,off:true,level:true}},{id:'example_cover',name:'Cortina da sala',aliases:[],actions:{open:true,close:true,stop:true}}];
export function tuyaPage(c,inspection,{E,I}){
 const connected=c.provider==='tuya'&&c.api.status==='connected';
 const bools=inspection?.spec?.functions?.filter(f=>String(f.type).toLowerCase()==='boolean')??[],states=inspection?.spec?.status?.filter(f=>String(f.type).toLowerCase()==='boolean')??[];
 return `<div class="page-heading"><div><p class="eyebrow">TUYA · SMART LIFE</p><h1>Seus dispositivos. Seu painel.</h1><p>Conexão direta à nuvem Tuya pelo servidor JM CONNECT.</p></div><a class="btn secondary" href="./guia-tuya-whatsapp.html" target="_blank" rel="noopener">${I('info')} Guia de instalação</a></div>
 <section class="connection-banner"><span class="connection-emblem">${I('plug')}</span><div><span class="kicker">JM CONNECT · R04</span><h2>${connected?'Servidor conectado':'Prepare a conexão com o Tuya'}</h2><p>${connected?`${c.api.catalog.length} canais cadastrados · ${c.api.controlEnabled?'comandos habilitados':'somente leitura'}`:'Configure os segredos Tuya e Meta no servidor. No tablet, informe somente a URL e a chave de acesso do JM CONNECT.'}</p></div></section>
 <div class="integration-grid"><section class="panel"><h2>1. Instalar o servidor</h2><p>O pacote contém a pasta gateway, os exemplos de configuração e o guia. O servidor precisa permanecer ligado para receber mensagens.</p><a class="btn secondary" href="./guia-tuya-whatsapp.html">Ler o guia completo</a></section><section class="panel"><h2>2. Conectar em leitura</h2><p>Configure seu projeto Tuya e selecione Tuya direto em Conexões reais. A conexão não aciona cargas.</p><a class="btn primary" href="#integracoes">${I('plug')} Abrir conexões</a></section></div>
 <section class="panel tuya-inspector"><h2>3. Identificar um dispositivo</h2><p>Informe o ID do seu projeto Tuya. Esta consulta não envia comandos.</p><form data-form="tuya-inspect"><label>ID do dispositivo Tuya<input name="deviceId" required maxlength="80" pattern="[a-zA-Z0-9_-]+" placeholder="ID real no projeto Tuya" ${!connected?'disabled':''}></label><button class="btn secondary" ${!connected?'disabled':''}>Consultar funções</button></form>
 ${inspection?`<div class="notice">${E(inspection.info.name)} · ${inspection.info.online?'online':'offline'} no Tuya</div><div class="tuya-spec"><table><thead><tr><th>Função</th><th>Tipo</th><th>Valores</th></tr></thead><tbody>${(inspection.spec.functions??[]).map(f=>`<tr><td>${E(f.code)}</td><td>${E(f.type)}</td><td><code>${E(typeof f.values==='string'?f.values:JSON.stringify(f.values))}</code></td></tr>`).join('')}</tbody></table></div>
 ${bools.length&&states.length?`<h3>Cadastrar saída liga/desliga</h3><p>Escolha comando e retorno correspondentes ao mesmo canal físico. Salvar apenas registra o vínculo.</p><form data-form="tuya-register" class="tuya-register"><input type="hidden" name="deviceId" value="${E(inspection.info.id)}"><label>Nome do canal<input name="name" maxlength="60" required placeholder="Luz da sala"></label><label>Identificador<input name="channelId" maxlength="60" pattern="[a-z0-9_]+" required placeholder="luz_sala"></label><label>Tipo<select name="type"><option value="light">Luz</option><option value="outlet">Tomada</option><option value="fan">Ventilador liga/desliga</option><option value="tv">TV liga/desliga</option></select></label><label>Comando<select name="code">${bools.map(f=>`<option value="${E(f.code)}">${E(f.code)}</option>`).join('')}</select></label><label>Retorno<select name="statusCode">${states.map(f=>`<option value="${E(f.code)}">${E(f.code)}</option>`).join('')}</select></label><label class="checkbox-row"><input name="inverted" type="checkbox"> Lógica invertida: false liga</label><button class="btn primary">Cadastrar canal em leitura</button></form>`:'<p>Use o guia para configurar mapeamentos específicos de cortina, intensidade ou temperatura.</p>'}`:''}</section>
 <section class="panel"><h2>Antes de habilitar comandos</h2><p>Vincule os canais aos cartões da casa em Conexões reais. Confira cada saída com uma carga de teste. O retorno da nuvem não substitui a observação do equipamento.</p><p class="field-help">Atualização periódica a cada 60 s enquanto conectado. Cotas e serviços da conta Tuya são necessários.</p></section>`;
}
export function whatsappPage(c,{E,I}){
 const connected=c.provider==='tuya'&&c.api.status==='connected',wa=connected?c.api.info?.whatsapp:null;
 return `<div class="page-heading"><div><p class="eyebrow">SUA CASA NA CONVERSA</p><h1>Comandos pelo WhatsApp</h1><p>Envie uma instrução ao bot. O JM CONNECT aciona o Tuya e responde com o resultado.</p></div><a class="btn secondary" href="./guia-tuya-whatsapp.html" target="_blank" rel="noopener">${I('info')} Configurar WhatsApp</a></div>
 <div class="wa-layout"><section class="panel wa-conversation"><span class="kicker">EXEMPLO ILUSTRATIVO · NENHUMA MENSAGEM ENVIADA</span><div class="wa-bubble outgoing">ligar luz da sala<small>Você</small></div><div class="wa-bubble incoming">Luz da sala: estado solicitado confirmado pelo Tuya.<small>Resposta após conferir o retorno</small></div><p>Também reconhece consultas de status e ajustes cadastrados para os equipamentos.</p>${wa?.botNumber?`<a class="btn primary" href="https://wa.me/${E(wa.botNumber)}?text=ajuda" target="_blank" rel="noopener noreferrer">Abrir conversa no WhatsApp</a>`:'<button class="btn secondary" disabled>Número do bot ainda não configurado</button>'}</section>
 <section class="panel"><h2>Ativação do serviço</h2><div class="wa-status"><span>Servidor Tuya</span><strong>${connected?'Conectado':'Não conectado'}</strong><span>Credenciais WhatsApp</span><strong>${wa?.configured?'Configuradas':'A configurar'}</strong><span>Números autorizados</span><strong>${wa?.authorizedCount??0}</strong><span>Controle WhatsApp</span><strong>${wa?.controlEnabled&&c.api.controlEnabled?'Habilitado no servidor':'Pausado / pendente'}</strong></div><p class="field-help">Parâmetros presentes não comprovam recebimento ou envio reais. Teste na sua conta.</p><div class="notice">O bot funciona no servidor, mesmo com o painel fechado. Desconectar o painel não pausa o WhatsApp.</div></section></div>
 <section class="panel"><span class="kicker">TESTE DE INTERPRETAÇÃO · SEM ACIONAMENTO</span><h2>Experimente a escrita do comando</h2><p>${connected?'Usa os nomes liberados no servidor.':'Usa exemplos fictícios: Luz da sala e Cortina da sala.'}</p><form data-form="wa-preview"><label>Mensagem de teste<input name="message" maxlength="180" required placeholder="ligar luz da sala"></label><button class="btn secondary">Testar interpretação</button></form><div id="wa-preview-result" role="status" class="notice" hidden></div><p class="field-help">Não envia mensagens nem comprova conexão com os dispositivos.</p></section>
 <section class="panel"><h2>Regras de operação</h2><div class="wa-rules"><p><strong>Números autorizados</strong><br>Somente remetentes cadastrados no servidor.</p><p><strong>Uma ação por mensagem</strong><br>Nomes exatos; negações e ambiguidades recusadas.</p><p><strong>Sem repetir acionamentos</strong><br>Identificação persistente de mensagens duplicadas.</p><p><strong>Resultado explícito</strong><br>Aceite e estado confirmado são separados.</p></div></section>`;
}
export function previewMessage(text,c){const live=c.provider==='tuya'&&c.api.status==='connected',devices=live?c.api.catalog.filter(d=>d.whatsapp):sampleCatalog,p=parseMessage(text,devices);if(p.error)return p.error;if(p.action==='help')return helpText;if(p.action==='list')return devices.map(d=>d.name).join(', ')||'Nenhum canal liberado.';return`Interpretação: ${p.action} → ${devices.find(d=>d.id===p.device)?.name}${p.value!==undefined?' · '+p.value:''}. Somente teste; nenhum comando enviado.`;}
